EXEC sys.sp_addextendedproperty @name=N'MS_BR_Purpose', @value=N'Consolida los folios pendientes de facturación (registrados o bloqueados) con datos del ingreso, paciente, entidad responsable, servicios/medicamentos, profesional quirúrgico y ubicación geográfica del centro de atención, para análisis y costeo.', @level0type=N'SCHEMA', @level0name=N'Billing', @level1type=N'VIEW', @level1name=N'A_Tocanc_Fact_Costos';
GO
EXEC sys.sp_addextendedproperty @name=N'MS_BR_Preconditions', @value=N'El detalle del control de ingresos (REVENUECONTROLDETAIL) debe estar en estado ''1'' (REGISTRADO) o ''3'' (BLOQUEADO).; El detalle de la orden de servicio (SERVICEORDERDETAIL.ISDELETE) no debe estar marcado como eliminado (''0'').; El ingreso (ADINGRESO.IESTADOIN) no debe estar en estado ''A'' ni ''C'' (anulado/cancelado).; Debe existir relación entre REVENUECONTROLDETAIL, SERVICEORDERDETAILDISTRIBUTION, SERVICEORDERDETAIL y REVENUECONTROL (INNER JOIN).', @level0type=N'SCHEMA', @level0name=N'Billing', @level1type=N'VIEW', @level1name=N'A_Tocanc_Fact_Costos';
GO
EXEC sys.sp_addextendedproperty @name=N'MS_BR_Invariants', @value=N'Solo se incluyen folios pendientes de facturar: STATUS distinto de ''2'' (FACTURADO).; Excluye ingresos anulados (''A'') y cancelados (''C''); los demás estados sí se incluyen (incluido ''F'').; Excluye líneas de orden de servicio marcadas como eliminadas (ISDELETE=''0'' es el filtro positivo retenido).; TOTAL A FACTURAR se calcula siempre como INVOICEDQUANTITY * RATEMANUALSALEPRICE de SERVICEORDERDETAIL.; EDAD_EN_CONSULTA se calcula con DATEDIFF en años entre fecha de nacimiento del paciente y fecha de ingreso.; Las coordenadas geográficas de los centros están cableadas en la vista (no provienen de tabla maestra).', @level0type=N'SCHEMA', @level0name=N'Billing', @level1type=N'VIEW', @level1name=N'A_Tocanc_Fact_Costos';
GO
EXEC sys.sp_addextendedproperty @name=N'MS_BR_SideEffects', @value=N'[RETURN_RESULT] Billing.A_Tocanc_Fact_Costos: Devuelve filas decodificando catálogos (FOLIOTYPE, LIQUIDATIONTYPE, STATUS, SERVICETYPE, RECORDTYPE, PRESENTATION, RESPONSIBLERECOVERYFEE, TIPCOBSAL) a etiquetas legibles en español, y calcula edad en consulta, descomposición de fechas (año/mes/día/nombre del mes) y bandera INGRESO_ALTA_MEDICA según SALIDA.FECALTPAC sea NULL o no.', @level0type=N'SCHEMA', @level0name=N'Billing', @level1type=N'VIEW', @level1name=N'A_Tocanc_Fact_Costos';
GO
EXEC sys.sp_addextendedproperty @name=N'MS_BR_Decisions', @value=N'si REVENUECONTROLDETAIL.FOLIOTYPE IN (''1'',''2'',''3'',''4'') → Clasifica el folio como EAPB CON CONTRATO / EAPB SIN CONTRATO / PARTICULARES / ASEGURADORAS; si REVENUECONTROLDETAIL.LIQUIDATIONTYPE IN (''1'',''2'',''3'',''4'') → Asigna tipo de liquidación: PAGO POR SERVICIOS / CAPITACION / FACTURA GLOBAL / CAPITACION GLOBAL; si REVENUECONTROLDETAIL.STATUS = ''1'' o ''3'' → Reporta el folio como REGISTRADO o BLOQUEADO (los FACTURADOS ''2'' quedan excluidos por el filtro del JOIN); si REVENUECONTROLDETAIL.RESPONSIBLERECOVERYFEE IN (''1'',''2'',''3'') → Identifica responsable de cuota de recuperación: NINGUNO / PACIENTE / TERCERO; si INPACIENT.TIPCOBSAL IN (''1''..''8'') → Asigna tipo de paciente (CONTRIBUTIVO, SUBSIDIADO TOTAL/PARCIAL, POBLACION POBRE SIN ASEGURAR CON/SIN SISBEN, DESPLAZADOS, PLAN DE SALUD ADICIONAL, OTROS) else Etiqueta el tipo de paciente como DESCONOCIDO; si SALIDA.FECALTPAC IS NULL → Marca el ingreso como ''SIN ALTA MÉDICA'' else Marca el ingreso como ''CON ALTA MÉDICA''; si CEN.NOMCENATE coincide con uno de los 8 centros listados (MARAYA, CIRCUNVALAR, SAN MARCEL, HOSPITALIZACION INFANTIL, CENTENARIO, SAN JUAN DE DIOS, ARTURO LOPEZ CARDONA, CARTAGO UNIDAD ONCOLOGICA) → Asigna coordenadas fijas (latitud/longitud) cableadas en el SQL para georreferenciar el centro de atención else UBICACION_LATITUD y UBICACION_LONGITUD quedan en NULL; si SERVICEORDERDETAIL.RECORDTYPE = ''1'' o ''2'' → Distingue si la línea corresponde a SERVICIOS o MEDICAMENTOS; si SERVICEORDERDETAIL.PRESENTATION IN (''1'',''2'',''3'') → Clasifica la presentación del servicio: NO QUIRÚRGICO / QUIRÚRGICO / PAQUETE', @level0type=N'SCHEMA', @level0name=N'Billing', @level1type=N'VIEW', @level1name=N'A_Tocanc_Fact_Costos';
GO
EXEC sys.sp_addextendedproperty @name=N'MS_BR_Consumes', @value=N'BILLING.REVENUECONTROLDETAIL; BILLING.SERVICEORDERDETAILDISTRIBUTION; BILLING.SERVICEORDERDETAIL; BILLING.REVENUECONTROL; DBO.INPACIENT; CONTRACT.CONTRACTENTITY; CONTRACT.CAREGROUP; BILLING.INVOICECATEGORIES; CONTRACT.CUPSENTITY; CONTRACT.IPSSERVICE; INVENTORY.INVENTORYPRODUCT; PAYROLL.FUNCTIONALUNIT; DBO.HCREGEGRE; DBO.HCREGEST; DBO.CHCAMASHO; CONTRACT.HEALTHADMINISTRATOR; COMMON.THIRDPARTY; DBO.ADINGRESO; DBO.ADCENATEN; DBO.INUNIFUNC; BILLING.SERVICEORDERDETAILSURGICAL; DBO.INPROFSAL; BILLING.SERVICEORDER', @level0type=N'SCHEMA', @level0name=N'Billing', @level1type=N'VIEW', @level1name=N'A_Tocanc_Fact_Costos';
GO
EXEC sys.sp_addextendedproperty @name=N'MS_BR_Source', @value=N'ai_claude-opus-4-7_tier-c_2026-05-06', @level0type=N'SCHEMA', @level0name=N'Billing', @level1type=N'VIEW', @level1name=N'A_Tocanc_Fact_Costos';
